<template>
    <div class="mobile-image-editor">
      <!-- 顶部导航栏 -->
      <div class="page-header">
        <h1 class="page-title">{{ t('imageEdit') }}</h1>
      </div>
  
      <!-- 主内容区域 -->
      <div class="page-content">
        <!-- 图片上传区域 -->
        <div class="upload-section">
          <div class="upload-container">
            <div class="image-preview-area">
              <MobileImageUploader
                ref="imageUploaderRef"
                :max-size="10 * 1024 * 1024"
                accept="image/png,image/jpeg,image/jpg"
                @onUploadSuccess="handleUploadSuccess"
                @onUploadRemove="handleUploadRemove"
              />
              <!-- Change/Delete按钮覆盖层 - 仅在有图片时显示 -->
              <div class="image-actions" v-if="formData.uploadedImageUrl">
                <div class="action-change" @click="handleChangeImage">
                  <span class="action-text">{{ t('change') }}</span>
                </div>
                <div class="action-divider"></div>
                <div class="action-delete" @click="removeImage">
                  <span class="action-text">{{ t('delete') }}</span>
                </div>
              </div>
            </div>
          </div>
        </div>

         <!-- 蒙版说明 -->
         <div class="mask-description">
            <div class="mask-title">{{ t('maskRequired') }}</div>
            <div class="mask-help">{{ t('drawOnImageToDefineArea') }}</div>
          </div>
  
        <!-- 图片编辑区域 -->
        <div v-if="formData.uploadedImageUrl" class="upload-section">
          <div class="upload-container">
            <div class="image-preview-area-edit">
              <!-- 图片编辑容器 -->
              <div class="image-container">
                <div class="image-wrapper" ref="imageWrapper">
                  <mobile-l-img
                    :src="formData.uploadedImageUrl"
                    class="edit-image"
                    @onLoad="onImageLoad"
                    w="100%"
                    h="100%"
                    radius="8px"
                    fit="contain"
                  />
                  <!-- 蒙版画布 -->
                  <canvas
                    ref="maskCanvas"
                    class="mask-canvas"
                    @mousedown="startDrawing"
                    @mousemove="draw"
                    @mouseup="stopDrawing"
                    @mouseleave="stopDrawing"
                    @touchstart="handleTouchStart"
                    @touchmove="handleTouchMove"
                    @touchend="handleTouchEnd"
                    @contextmenu="preventDefault"
                  ></canvas>
                </div>
              </div>
              
            </div>
          </div>
  
         
  
          <!-- 工具栏 -->
          <div class="edit-toolbar-container">
            <div class="toolbar-button" @click="handleUndoMask">
              <mobile-l-img w="12px" h="12px" :src="'/static/images/draw-pre-icon.png'" />
            </div>
            <div class="toolbar-button" @click="handleRedoMask">
              <mobile-l-img w="12px" h="12px" :src="'/static/images/draw-next-icon.png'" />
            </div>
            <div class="toolbar-button" @click="handleClearMask">
              <mobile-l-img w="12px" h="12px" :src="'/static/images/draw-clear-icon.png'" />
            </div>
            <div class="toolbar-button" @click="handleDownloadMask">
              <mobile-l-img w="12px" h="12px" :src="'/static/images/draw-down-icon.png'" />
            </div>
          </div>
        </div>
  
        <!-- 表单配置区域 -->
        <div class="form-section">
          <!-- 提示词输入 -->
          <div class="form-item">
            <div class="form-label">{{ t('prompt') }}</div>
            <div class="form-input">
              <textarea
                v-model="formData.prompt"
                :placeholder="t('describePromptForModifyingImage')"
                class="prompt-textarea"
                rows="4"
              ></textarea>
            </div>
            <div v-if="promptError" class="form-error">{{ promptError }}</div>
          </div>
  
          <!-- 种子值输入 -->
          <div class="form-item">
            <div class="form-label">{{ t('seedOptional') }}</div>
            <div class="form-input">
              <input
                v-model="formData.seed"
                type="number"
                :placeholder="t('enterSeedNumber')"
                class="seed-input"
              />
            </div>
          </div>
  
          <!-- 高级模式开关 -->
          <div class="form-item switch-item">
            <div class="switch-left">
              <div class="form-label">{{ t('advancedMode') }}</div>
              <div class="switch-description">{{ t('muchBetterResult') }}</div>
            </div>
            <div class="switch-right">
              <div 
                class="custom-switch"
                :class="{ active: formData.advancedMode }"
                @click="toggleAdvancedMode"
              >
                <div class="switch-handle"></div>
              </div>
            </div>
          </div>
        </div>
  
        <!-- 错误提示 -->
        <div v-if="formError" class="form-error-section">
          <div class="form-error">{{ formError }}</div>
        </div>
      </div>
  
      <!-- 底部按钮占位区域 -->
      <div class="empty-quality-selector-area" :style="{ height: '80px' }"></div>
  
      <!-- 底部操作按钮区域 -->
      <div class="quality-selector-area">
        <div class="generate-button-wrapper">
          <div class="generate-button-container">
            <button
              class="generate-button"
              :class="{ 'generate-button--disabled': isButtonDisabled }"
              :disabled="isButtonDisabled"
              @click="handleGenerate"
            >
              <div v-if="isGenerating" class="loading-icon">⏳</div>
              {{ isGenerating ? t('generating') : t('generateImage') }}
            </button>
          </div>
        </div>
      </div>
    </div>
  </template>
  
  <script setup>
  import { ref, reactive, computed, onMounted, onUnmounted, nextTick } from 'vue';
  import { useI18n } from 'vue-i18n';
  import MobileImageUploader from '@/mobile/components/mobile-image-uploader.vue';
  import MobileLImg from '@/mobile/components/mobile-l-img.vue';
  import { useMediaGenerationStore } from '@/store/modules/media-generation';
  import { IMAGE_OPERATIONS } from '@/types/media-tool';
  
  const { t } = useI18n();
  const mediaStore = useMediaGenerationStore();
  
  // 当前模块的 key
  const MODULE_KEY = IMAGE_OPERATIONS.EDIT;
  
  // 组件引用
  const imageUploaderRef = ref(null);
  const imageWrapper = ref(null);
  const maskCanvas = ref(null);
  
  // 表单数据
  const formData = reactive({
    uploadedImageUrl: '',
    uploadedImage: null,
    uploadedImageDimensions: null,
    prompt: '',
    seed: '',
    advancedMode: false
  });
  
  // 状态管理
  const isGenerating = ref(false);
  const promptError = ref('');
  const formError = ref('');
  
  // Canvas 绘制相关
  let ctx = null;
  const brushSize = ref(20);
  const isDrawing = ref(false);
  const lastPoint = ref(null);
  const canvasHistory = ref([]);
  const historyIndex = ref(-1);
  
  // 计算属性
  const isButtonDisabled = computed(() => {
    return !formData.uploadedImageUrl || !formData.prompt.trim();
  });
  
  // 图片上传处理
  const handleUploadSuccess = (result) => {
    
    // 处理图片URL - 确保包含完整的OSS路径
    const baseUrl = import.meta.env.VITE_APP_OSS_PIC_PATH || '';
    const imageUrl = result.url;
    const fullImageUrl = imageUrl.startsWith('http') ? imageUrl : baseUrl + imageUrl;
    
    formData.uploadedImageUrl = fullImageUrl;
    formData.uploadedImage = result.originalFile;
    formData.uploadedImageDimensions = result.dimensions;
    formError.value = '';
    
    // 清除旧的蒙版
    clearMask();
    
    // 重新初始化画布（延迟执行确保DOM更新）
    nextTick(() => {
        initCanvas();
    });
  };
  
  const handleUploadRemove = () => {
    console.log('Image upload removed');
    formData.uploadedImageUrl = '';
    formData.uploadedImage = null;
    formData.uploadedImageDimensions = null;
    clearMask();
  };
  
  // 更换图片
  const handleChangeImage = () => {
    if (imageUploaderRef.value) {
      // 直接调用上传组件的选择文件方法
      const fileInput = imageUploaderRef.value.$el.querySelector('input[type="file"]');
      if (fileInput) {
        fileInput.click();
      } else {
        // 如果找不到文件输入框，尝试调用组件的方法
        if (typeof imageUploaderRef.value.chooseFile === 'function') {
          imageUploaderRef.value.chooseFile();
        } else if (typeof imageUploaderRef.value.selectFile === 'function') {
          imageUploaderRef.value.selectFile();
        } else {
          console.warn('Could not trigger file selection');
        }
      }
    }
  };
  
  // 移除图片
  const removeImage = () => {
    // 调用上传组件的重置方法
    if (imageUploaderRef.value) {
      imageUploaderRef.value.reset();
    }
    formData.uploadedImageUrl = '';
    formData.uploadedImage = null;
    formData.uploadedImageDimensions = null;
    clearMask();
  };
  
  // 图片加载完成事件
  const onImageLoad = () => {
    // 延迟初始化画布，确保DOM已更新
    nextTick(() => {
      setTimeout(() => {
        initCanvas();
      }, 50);
    });
  };
  
  // 初始化Canvas
  const initCanvas = () => {
    if (!maskCanvas.value || !imageWrapper.value) {
      console.warn('Canvas or wrapper element not found');
      return;
    }
    
    const canvas = maskCanvas.value;
    const img = imageWrapper.value.querySelector('img');
    
    if (!img) {
      console.warn('Image element not found');
      return;
    }
    
    // 等待图片完全加载
    if (!img.complete) {
      img.onload = () => initCanvas();
      return;
    }
    
    // 获取容器和图片的实际尺寸
    const containerRect = imageWrapper.value.getBoundingClientRect();
    const imgNaturalWidth = img.naturalWidth;
    const imgNaturalHeight = img.naturalHeight;
    
    if (!imgNaturalWidth || !imgNaturalHeight) {
      console.warn('Image natural dimensions are zero');
      return;
    }
    
    // 计算图片在容器中的实际显示尺寸（考虑object-fit: contain）
    const containerAspect = containerRect.width / containerRect.height;
    const imageAspect = imgNaturalWidth / imgNaturalHeight;
    
    let displayWidth, displayHeight, offsetX, offsetY;
    
    if (imageAspect > containerAspect) {
      // 图片更宽，以宽度为准
      displayWidth = containerRect.width;
      displayHeight = containerRect.width / imageAspect;
      offsetX = 0;
      offsetY = (containerRect.height - displayHeight) / 2;
    } else {
      // 图片更高，以高度为准
      displayWidth = containerRect.height * imageAspect;
      displayHeight = containerRect.height;
      offsetX = (containerRect.width - displayWidth) / 2;
      offsetY = 0;
    }
    
    // 设置画布尺寸和位置
    canvas.width = displayWidth;
    canvas.height = displayHeight;
    canvas.style.width = displayWidth + 'px';
    canvas.style.height = displayHeight + 'px';
    canvas.style.left = offsetX + 'px';
    canvas.style.top = offsetY + 'px';
    
    // 获取绘图上下文
    const context = canvas.getContext('2d');
    if (!context) {
      console.error('Failed to get canvas 2D context');
      return;
    }
    
    ctx = context;
    ctx.globalCompositeOperation = 'source-over';
    ctx.strokeStyle = 'rgba(255, 255, 255, 1)';
    ctx.fillStyle = 'rgba(255, 255, 255, 1)';
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';
    
    // 初始化历史记录
    canvasHistory.value = [];
    historyIndex.value = -1;
    saveCanvasState();
  };
  
  // Canvas 绘制相关方法
  const getCanvasPoint = (event) => {
    const canvas = maskCanvas.value;
    if (!canvas) return { x: 0, y: 0 };
    
    const canvasRect = canvas.getBoundingClientRect();
    const scaleX = canvas.width / canvasRect.width;
    const scaleY = canvas.height / canvasRect.height;
    
    return {
      x: (event.clientX - canvasRect.left) * scaleX,
      y: (event.clientY - canvasRect.top) * scaleY
    };
  };
  
  const startDrawing = (event) => {
    if (!ctx || !maskCanvas.value || maskCanvas.value.width === 0 || maskCanvas.value.height === 0) return;
    
    isDrawing.value = true;
    const point = getCanvasPoint(event);
    lastPoint.value = point;
    ctx.lineWidth = brushSize.value;
    ctx.beginPath();
    ctx.arc(point.x, point.y, brushSize.value / 2, 0, 2 * Math.PI);
    ctx.fill();
  };
  
  const draw = (event) => {
    if (!isDrawing.value || !ctx || !maskCanvas.value || !lastPoint.value) return;
    const currentPoint = getCanvasPoint(event);
    ctx.lineWidth = brushSize.value;
    ctx.beginPath();
    ctx.moveTo(lastPoint.value.x, lastPoint.value.y);
    ctx.lineTo(currentPoint.x, currentPoint.y);
    ctx.stroke();
    lastPoint.value = currentPoint;
  };
  
  const stopDrawing = () => {
    if (!isDrawing.value) return;
    
    isDrawing.value = false;
    lastPoint.value = null;
    saveCanvasState();
  };
  
  // 触摸事件处理
  const handleTouchStart = (event) => {
    event.preventDefault();
    if (event.touches.length === 1) {
      const touch = event.touches[0];
      const mouseEvent = new MouseEvent('mousedown', {
        clientX: touch.clientX,
        clientY: touch.clientY,
      });
      startDrawing(mouseEvent);
    }
  };
  
  const handleTouchMove = (event) => {
    event.preventDefault();
    if (event.touches.length === 1 && isDrawing.value) {
      const touch = event.touches[0];
      const mouseEvent = new MouseEvent('mousemove', {
        clientX: touch.clientX,
        clientY: touch.clientY,
      });
      draw(mouseEvent);
    }
  };
  
  const handleTouchEnd = (event) => {
    event.preventDefault();
    stopDrawing();
  };
  
  const preventDefault = (event) => {
    event.preventDefault();
    return false;
  };
  
  // Canvas 历史记录管理
  const saveCanvasState = () => {
    if (!maskCanvas.value || !ctx) return;
    const canvas = maskCanvas.value;
    if (canvas.width === 0 || canvas.height === 0) return;
    
    try {
      const imageData = ctx.getImageData(0, 0, canvas.width, canvas.height);
      
      if (historyIndex.value < canvasHistory.value.length - 1) {
        canvasHistory.value = canvasHistory.value.slice(0, historyIndex.value + 1);
      }
      
      canvasHistory.value.push(imageData);
      historyIndex.value = canvasHistory.value.length - 1;
      
      if (canvasHistory.value.length > 20) {
        canvasHistory.value.shift();
        historyIndex.value--;
      }
    } catch (error) {
      console.warn('Failed to save canvas state:', error);
    }
  };
  
  const undoMask = () => {
    if (!ctx || !maskCanvas.value || canvasHistory.value.length < 1 || historyIndex.value <= 0) return;
    
    try {
      historyIndex.value--;
      const imageData = canvasHistory.value[historyIndex.value];
      ctx.putImageData(imageData, 0, 0);
    } catch (error) {
      console.warn('Failed to undo:', error);
    }
  };
  
  const redoMask = () => {
    if (!ctx || !maskCanvas.value || historyIndex.value >= canvasHistory.value.length - 1) return;
    
    try {
      historyIndex.value++;
      const imageData = canvasHistory.value[historyIndex.value];
      ctx.putImageData(imageData, 0, 0);
    } catch (error) {
      console.warn('Failed to redo:', error);
    }
  };
  
  const clearMask = () => {
    if (ctx && maskCanvas.value) {
      ctx.clearRect(0, 0, maskCanvas.value.width, maskCanvas.value.height);
      const imageData = ctx.getImageData(0, 0, maskCanvas.value.width, maskCanvas.value.height);
      canvasHistory.value = [imageData];
      historyIndex.value = 0;
    }
  };
  
  const downloadMask = () => {
    if (!maskCanvas.value || maskCanvas.value.width === 0 || maskCanvas.value.height === 0) {
      formError.value = t('noMaskToDownload');
      return;
    }
    try {
      const link = document.createElement('a');
      link.download = 'mask.png';
      link.href = maskCanvas.value.toDataURL();
      link.click();
    } catch (error) {
      console.error('Failed to download mask:', error);
      formError.value = t('failedToDownloadMask');
    }
  };
  
  // 工具栏事件处理
  const handleUndoMask = () => undoMask();
  const handleRedoMask = () => redoMask();
  const handleClearMask = () => clearMask();
  const handleDownloadMask = () => downloadMask();
  
  // 高级模式切换
  const toggleAdvancedMode = () => {
    formData.advancedMode = !formData.advancedMode;
  };
  
  // 表单验证
  const validateForm = () => {
    promptError.value = '';
    formError.value = '';
    
    // 验证图片
    if (!formData.uploadedImageUrl) {
      formError.value = t('imageRequired');
      return false;
    }
    
    // 验证提示词
    if (!formData.prompt.trim()) {
      promptError.value = t('promptRequired');
      return false;
    }
    
    return true;
  };
  
  // 生成图片
  const handleGenerate = async () => {
    if (!validateForm()) return;
    
    try {
      isGenerating.value = true;
      formError.value = '';
      
      // 获取蒙版数据
      let maskDataURL = null;
      if (maskCanvas.value && ctx) {
        const imageData = ctx.getImageData(0, 0, maskCanvas.value.width, maskCanvas.value.height);
        const data = imageData.data;
        let hasContent = false;
        for (let i = 3; i < data.length; i += 4) {
          if (data[i] > 0) {
            hasContent = true;
            break;
          }
        }
        if (hasContent) {
          maskDataURL = maskCanvas.value.toDataURL();
        }
      }
      
      // 准备请求数据
      const requestData = {
        uploadedImage: formData.uploadedImage,
        uploadedImageUrl: formData.uploadedImageUrl,
        uploadedImageDimensions: formData.uploadedImageDimensions,
        prompt: formData.prompt.trim(),
        seed: formData.seed,
        advancedMode: formData.advancedMode,
        maskDataURL: maskDataURL
      };
      
      console.log('Mobile image editing with data:', requestData);
      
      // TODO: 调用API
      // 模拟处理时间
      await new Promise(resolve => setTimeout(resolve, 2000));
      
      // 模拟成功结果
      console.log('Image editing completed successfully');
      
    } catch (error) {
      console.error('Image editing failed:', error);
      formError.value = t('generateImageFailed');
    } finally {
      isGenerating.value = false;
    }
  };
  
  // 获取存储的生成结果
  const loadGenerationResult = () => {
    const result = mediaStore.getGenerationResult(MODULE_KEY);
    if (result && result.imageUrl) {
      // 处理图片URL - 确保包含完整的OSS路径
      const baseUrl = import.meta.env.VITE_APP_OSS_PIC_PATH || '';
      const imageUrl = result.imageUrl;
      const fullImageUrl = imageUrl.startsWith('http') ? imageUrl : baseUrl + imageUrl;
      
      // 直接设置formData中的图片数据
      formData.uploadedImageUrl = fullImageUrl;
      
      // 清除生成结果，避免重复使用
      mediaStore.clearGenerationResult(MODULE_KEY);
    }
  };
  
  // 生命周期
  onMounted(() => {
    // 检测Pinia中是否有生成的图片
    loadGenerationResult();
    
    // 初始化
    // 添加窗口大小变化监听器
    window.addEventListener('resize', handleResize);
  });
  
  onUnmounted(() => {
    // 清理
    // 清理监听器
    window.removeEventListener('resize', handleResize);
  });
  
  // 窗口大小变化处理
  const handleResize = () => {
    if (formData.uploadedImageUrl && maskCanvas.value) {
      // 延迟重新初始化，确保布局已更新
      setTimeout(() => {
        initCanvas();
      }, 100);
    }
  };
  </script>
  
